css:
#card { position:absolute; left:50%; bottom:92px; transform:translateX(-50%); text-align:center; }
#where { display:inline-block; background:#fff; color:var(--red); font-weight:700; font-size:34px; letter-spacing:.16em; padding:10px 26px 8px; }
#date { background:var(--red); color:#fff; font-weight:700; font-size:78px; letter-spacing:.03em; padding:14px 46px 10px; box-shadow:0 18px 50px rgba(0,0,0,.45); white-space:nowrap; }

js:
document.getElementById('where').textContent = V.where;
document.getElementById('date').textContent = V.date;
const D = V.duration;
tl.fromTo('#date', { scale: 0.6, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.45, ease: 'back.out(1.7)' }, 0.15);
tl.fromTo('#where', { y: 30, opacity: 0 }, { y: 0, opacity: 1, duration: 0.35, ease: 'power3.out' }, 0.45);
tl.to('#card', { opacity: 0, duration: 0.35 }, D - 0.4);
